local GRIP = CFrame.new(0, 0, 0, 1, 0, 0, 0, 1, 0, 0, 0, 1)

local function build(): Tool
	local tool = Instance.new("Tool")
	tool.Name = "Gravestair"
	tool.ToolTip = "Gravestair"
	tool.RequiresHandle = true
	tool.Grip = GRIP

	local handle: BasePart
	for _, def in PARTS do
		local name, class, size, offset, styleId = def[1], def[2], def[3], def[4], def[5]
		local style = STYLES[styleId]
		local part = Instance.new(class)
		part.Name = name
		part.Size = size
		part.Color = style.Color
		part.Material = style.Material
		part.Reflectance = style.Reflectance
		part.Transparency = style.Transparency
		part.TopSurface = Enum.SurfaceType.Smooth
		part.BottomSurface = Enum.SurfaceType.Smooth
		part.Anchored = false
		part.CanCollide = false
		part.Massless = true
		if name == "Handle" then
			handle = part
			part.CFrame = CFrame.identity
		else
			part.CanTouch = false
			part.CanQuery = false
			part.CFrame = handle.CFrame * offset
			local weld = Instance.new("WeldConstraint")
			weld.Name = "WeaponWeld"
			weld.Part0 = handle
			weld.Part1 = part
			weld.Parent = part
		end
		part.Parent = tool
	end
	return tool
end

-- Run from the command bar: `script` is nil there.
if not script then
	local tool = build()
	tool.Parent = game:GetService("StarterPack")
	local display = build()
	for _, d in display:GetDescendants() do
		if d:IsA("BasePart") then d.Anchored = true end
	end
	display.Handle.CFrame = CFrame.new(0, 4, 0) * display.Handle.CFrame
	display.Parent = workspace
	print("Built Gravestair: Tool in StarterPack, anchored display copy in Workspace at (0, 4, 0)")
end

return { build = build }
